import type { FilterValue, Option } from 'models/Filters';

export type CommercialSkuOption = Option & {
  sub_brand?: string;
};

export type CommercialSkuDimension = {
  values?: Record<string, CommercialSkuOption[]>;
};

const isActiveSubBrand = (
  subBrand: FilterValue | undefined,
): subBrand is string =>
  subBrand != null &&
  subBrand !== '' &&
  String(subBrand).toLowerCase() !== 'all';

export const isCommercialSkuOption = (
  option: Option,
): option is CommercialSkuOption =>
  typeof option === 'object' &&
  option !== null &&
  'sub_brand' in option &&
  typeof (option as CommercialSkuOption).sub_brand === 'string';

export const getCommercialSkuOptions = (
  sku: CommercialSkuDimension | undefined,
  brand: FilterValue | undefined,
  subBrand?: FilterValue,
): CommercialSkuOption[] => {
  if (!brand || String(brand).toLowerCase() === 'all') {
    return [];
  }

  const brandOptions = sku?.values?.[String(brand)] ?? [];
  if (!isActiveSubBrand(subBrand)) {
    return brandOptions;
  }

  return brandOptions.filter(
    (option) => !isCommercialSkuOption(option) || option.sub_brand === subBrand,
  );
};

export const findSubBrandForSku = (
  options: CommercialSkuOption[],
  skuValue: FilterValue,
): string | undefined => {
  if (
    skuValue == null ||
    skuValue === '' ||
    String(skuValue).toLowerCase() === 'all'
  ) {
    return undefined;
  }

  const match = options.find(
    (option) =>
      option.value === skuValue &&
      isCommercialSkuOption(option) &&
      option.sub_brand,
  );

  return match?.sub_brand;
};

export const shouldAutoLinkSubBrandForSku = (
  currentSubBrand: FilterValue | undefined,
  linkedSubBrand: string | undefined,
): linkedSubBrand is string =>
  Boolean(
    linkedSubBrand &&
    (!isActiveSubBrand(currentSubBrand) || currentSubBrand !== linkedSubBrand),
  );

export const isActiveCommercialSku = (
  sku: FilterValue | undefined,
): sku is string =>
  sku != null && sku !== '' && String(sku).toLowerCase() !== 'all';

export const shouldClearSkuWhenSubBrandCleared = (
  currentSubBrand: FilterValue | undefined,
  currentSku: FilterValue | undefined,
): boolean =>
  !isActiveSubBrand(currentSubBrand) && isActiveCommercialSku(currentSku);
